      {Object.entries(TF_CONFIG).map(([key, cfg]) => (
        <div key={key} onClick={() => setTf(key)} style={{ padding: "5px 14px", cursor: "pointer", borderBottom: tf === key ? `2px solid ${cfg.color}` : "2px solid transparent" }}>
          <div style={{ fontSize: 9, fontWeight: 700, letterSpacing: 1, color: tf === key ? cfg.color : t.textGhost, ...M }}>{cfg.label}</div>
          <div style={{ fontSize: 7, color: t.textGhost, ...M }}>{cfg.sub}</div>
        </div>
      ))}
