function IntelScreen({ t, tf, setTf }) {
  const [view, setView] = useState("TEC");
  const tabs = [
    { key: "NAR", label: "NAR", color: typeColors.NAR },
    { key: "TEC", label: "TEC", color: typeColors.TEC },
    { key: "FUN", label: "FUN", color: typeColors.FUN },
    { key: "FLO", label: "FLO", color: typeColors.FLO },
  ];
  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <div style={{ display: "flex", gap: 0, borderBottom: `1px solid ${t.border}`, justifyContent: "center" }}>
        {tabs.map(tb => (
          <div key={tb.key} onClick={() => setView(tb.key)} style={{ padding: "6px 12px", cursor: "pointer", fontSize: 10, fontWeight: 700, letterSpacing: 1, color: view === tb.key ? tb.color : t.textGhost, borderBottom: view === tb.key ? `2px solid ${tb.color}` : "2px solid transparent" }}>{tb.label}</div>
        ))}
      </div>
      <div style={{ flex: 1, overflow: "hidden" }}>
        {view === "NAR" && <NarView t={t} />}
        {view === "TEC" && <TecView t={t} tf={tf} setTf={setTf} />}
        {view === "FUN" && <FunView t={t} />}
        {view === "FLO" && <FloView t={t} />}
      </div>
    </div>
  );
}

function SignalsTecView({ t, tf }) {
  const [sortBy, setSortBy] = React.useState('sc');
  const [asc, setAsc] = React.useState(false);
  
  const scoreKey = tf === "sw" ? "st" : tf === "lt" ? "ltt" : "pt";
  const passKey = tf === "sw" ? "iSW" : tf === "lt" ? "iLT" : "iPOS";
  const whyKey = tf === "sw" ? "sw" : tf === "lt" ? "lw" : "pw";
  const oppKey = tf === "sw" ? "so" : tf === "lt" ? "lo" : "po";
  const momKey = tf === "sw" ? "sm" : tf === "lt" ? "lm" : "pm";
  const label = tf === "sw" ? "SWING" : tf === "lt" ? "LONG TERM" : "POSITION";
  const color = tf === "sw" ? "#22c55e" : tf === "lt" ? "#f59e0b" : "#3b82f6";
  
  const filtered = TEC_SYNTHESIS.filter(d => d[passKey]);
  const withSc = filtered.map(d => ({...d, sc: d[scoreKey], opp_v: d[oppKey], mom_v: d[momKey], reasons: (d[whyKey]||[]).join(" · ")}));
  const sorted = [...withSc].sort((a,b) => {
    const av = a[sortBy] ?? 0, bv = b[sortBy] ?? 0;
    return asc ? (av > bv ? 1 : -1) : (av < bv ? 1 : -1);
  });
  const doSort = (col) => { if (sortBy === col) setAsc(!asc); else { setSortBy(col); setAsc(false); }};
  const hdr = (label, col, w) => (
    <div key={col} onClick={() => doSort(col)} style={{ padding: "4px 0", color: sortBy === col ? "#22c55e" : t.textGhost, borderBottom: `1px solid ${t.border}`, fontWeight: 600, fontSize: 8, cursor: "pointer", width: w }}>{label}{sortBy === col ? (asc ? " ↑" : " ↓") : ""}</div>
  );
  return (
    <ScrollArea style={{ padding: "6px 8px" }}>
      <div style={{ ...M, fontSize: 9, color: color, padding: "4px 0 8px", fontWeight: 600 }}>{label}: {filtered.length} stocks with TEC ≥ 65</div>
      <div style={{ display: "flex", gap: 0, ...M, borderBottom: `1px solid ${t.border}` }}>
        {[["#","sc",28],["TICK","t",50],["$","p",56],["TEC","sc",36],["OPP","opp_v",36],["MOM","mom_v",36],["G","g",22],["SIGNALS","reasons",360],["SEC","sec",80]].map(([l,c,w]) => hdr(l,c,w))}
      </div>
      {sorted.map((d, i) => (
        <div key={i} style={{ display: "flex", gap: 0, padding: "3px 0", borderBottom: `1px solid ${t.border}08`, ...M, fontSize: 10 }}>
          <div style={{ width: 28, color: i < 20 ? "#22c55e" : i < 50 ? "#f59e0b" : t.textGhost, fontWeight: 700 }}>{i+1}</div>
          <div style={{ width: 50, color: "#22c55e", fontWeight: 600 }}>{d.t}</div>
          <div style={{ width: 56, color: t.text }}>${d.p}</div>
          <div style={{ width: 36, color: d.sc >= 75 ? "#22c55e" : d.sc >= 65 ? "#f59e0b" : t.text, fontWeight: 700 }}>{d.sc}</div>
          <div style={{ width: 36, color: d.opp_v >= 75 ? "#22c55e" : d.opp_v >= 55 ? "#f59e0b" : t.textBody }}>{d.opp_v}</div>
          <div style={{ width: 36, color: d.mom_v >= 75 ? "#22c55e" : d.mom_v >= 55 ? "#f59e0b" : t.textBody }}>{d.mom_v}</div>
          <div style={{ width: 22, color: d.g === "A" ? "#22c55e" : d.g === "F" ? "#ef4444" : t.textBody, fontWeight: 600 }}>{d.g}</div>
          <div style={{ width: 360, fontSize: 8 }}>
            <span style={{ color: color }}>{d.reasons}</span>
            {d.w && <span style={{ color: "#ef4444", marginLeft: 6 }}>⚠ {d.w}</span>}
          </div>
          <div style={{ width: 80, color: t.textGhost, fontSize: 8 }}>{d.sec}</div>
        </div>
      ))}
    </ScrollArea>
  );
}

