function SignalsNarFeedView({ t }) {
  const [openGroup, setOpenGroup] = useState({});
  const items = typeof SIGNALS_NAR_DATA !== 'undefined' ? SIGNALS_NAR_DATA : {};
  const groups = Object.entries(items);
  const sigColors = { BULLISH: "#22c55e", WATCH: "#f59e0b", CAUTIOUS: "#64748b", RISK: "#ef4444" };
  const dirColors = { LONG: "#22c55e", WATCH: "#f59e0b", HOLD: "#3b82f6", CAUTION: "#ef4444", RISK: "#ef4444" };
  return (
    <ScrollArea style={{ padding: "8px" }}>
      <div style={{ ...M, fontSize: 9, color: t.textMuted, padding: "4px 0 8px" }}>Narrative-driven trade signals. Stocks you'd trade based on what the world is saying right now.</div>
      {groups.map(([name, data], i) => {
        const sc = sigColors[data.signal] || "#64748b";
        const isOpen = openGroup[name];
        const stockCount = (data.stocks || []).length;
        return (
          <div key={i} style={{ margin: "4px 0", background: t.bgCard, borderRadius: 6, borderLeft: `3px solid ${sc}` }}>
            <div onClick={() => setOpenGroup({...openGroup, [name]: !isOpen})} style={{ padding: "8px 10px", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div style={{ flex: 1 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <span style={{ color: sc, fontWeight: 700, fontSize: 10, letterSpacing: 0.5 }}>{name}</span>
                  <span style={{ ...M, fontSize: 8, padding: "1px 6px", borderRadius: 3, background: `${sc}20`, color: sc, fontWeight: 700 }}>{data.signal} {data.conf}%</span>
                </div>
                <div style={{ color: t.textMuted, fontSize: 9, marginTop: 3, lineHeight: 1.3 }}>{(data.thesis || "").slice(0, 140)}{(data.thesis || "").length > 140 ? "..." : ""}</div>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 6, flexShrink: 0, marginLeft: 8 }}>
                <div style={{ display: "flex", gap: 3 }}>
                  {(data.stocks || []).slice(0, 5).map((s, j) => (
                    <span key={j} style={{ ...M, fontSize: 8, padding: "1px 4px", borderRadius: 2, background: `${dirColors[s.dir] || "#64748b"}15`, color: dirColors[s.dir] || "#64748b", fontWeight: 600 }}>{s.t}</span>
                  ))}
                </div>
                <span style={{ color: t.textGhost, fontSize: 10 }}>{isOpen ? "▾" : "▸"}</span>
              </div>
            </div>
            {isOpen && (
              <div style={{ padding: "0 10px 10px" }}>
                <div style={{ ...M, fontSize: 9, color: t.textBody, padding: "0 0 8px", lineHeight: 1.4 }}>{data.thesis}</div>
                {(data.stocks || []).map((s, j) => (
                  <div key={j} style={{ display: "flex", gap: 8, padding: "5px 0", borderBottom: `1px solid ${t.border}10`, alignItems: "flex-start" }}>
                    <span style={{ ...M, width: 40, fontSize: 10, color: dirColors[s.dir] || t.text, fontWeight: 700, flexShrink: 0 }}>{s.t}</span>
                    <span style={{ ...M, width: 30, fontSize: 8, padding: "1px 3px", borderRadius: 2, background: `${dirColors[s.dir] || "#64748b"}15`, color: dirColors[s.dir] || "#64748b", fontWeight: 600, textAlign: "center", flexShrink: 0 }}>{s.dir}</span>
                    {s.rel != null && <span style={{ ...M, width: 28, fontSize: 8, color: s.rel >= 85 ? "#22c55e" : s.rel >= 70 ? "#f59e0b" : "#64748b", fontWeight: 600, flexShrink: 0 }}>{s.rel}%</span>}
                    <span style={{ ...M, fontSize: 9, color: t.textBody, lineHeight: 1.3 }}>{s.why}</span>
                  </div>
                ))}
                <div style={{ ...M, fontSize: 8, color: t.textGhost, marginTop: 6, paddingTop: 4, borderTop: `1px solid ${t.border}15` }}>
                  {data.evidence} articles · {data.sources}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </ScrollArea>
  );
}
